def load(rows: list[str]) -> dict[str, int]:
    result: dict[str, int] = {}
    for row in rows:
        row = row.strip()
        if not row:
            continue
        try:
            name, value = row.split(",")
            result[name] = int(value)
        except ValueError:
            continue
    return result


data = ["Ada,90", "", "Brian,oops", "Grace", "Alan,60"]
scores = load(data)

print(len(scores), sum(scores.values()))
```

